def findLatestTime(s: str) -> str:
    # Convert string to list to allow modifications
    time = list(s)

    # Handle the Hours part (HH)
    # The maximum value for HH is 11.

    # First digit of HH
    if time[0] == '?':
        # If the second digit is '?', we can set the first to '1' (for 11:xx)
        # If the second digit is '0' or '1', we can set the first to '1'
        # If the second digit is '2'-'9', the first must be '0'
        if time[1] == '?' or time[1] == '0' or time[1] == '1':
            time[0] = '1'
        else:
            time[0] = '0'

    # Second digit of HH
    if time[1] == '?':
        # If the first digit is '1', the max second digit is '1' (to get 11)
        # If the first digit is '0', the max second digit is '9' (to get 09)
        if time[0] == '1':
            time[1] = '1'
        else:
            time[1] = '9'

    # Handle the Minutes part (MM)
    # The maximum value for MM is 59.

    # First digit of MM (Tens place)
    if time[3] == '?':
        time[3] = '5'

    # Second digit of MM (Units place)
    if time[4] == '?':
        time[4] = '9'

    return "".join(time)
