import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    grid = input_data[2:]

    # Pre-calculate which cells are "frozen" (adjacent to a magnet)
    # 0: safe to move from, 1: magnet, 2: frozen (adjacent to magnet)
    status = [[0] * W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#':
                status[r][c] = 1
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if grid[nr][nc] == '.':
                            status[nr][nc] = 2

    visited = [[False] * W for _ in range(H)]
    # To track which frozen cells were reached in the current BFS/DFS
    # to avoid counting them multiple times for the same component
    last_seen_frozen = [[-1] * W for _ in range(H)]

    max_freedom = 0
    component_id = 0

    for r in range(H):
        for c in range(W):
            # We only start a search from a non-magnet, non-frozen cell
            # to explore a connected component of "free" cells.
            if status[r][c] == 0 and not visited[r][c]:
                component_id += 1
                q = [(r, c)]
                visited[r][c] = True
                count = 0

                # BFS to find all reachable cells
                idx = 0
                while idx < len(q):
                    curr_r, curr_c = q[idx]
                    idx += 1
                    count += 1

                    # If current cell is status 0, we can move to neighbors
                    # If it were status 2, we wouldn't add neighbors (it's a leaf)
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if status[nr][nc] == 0:
                                if not visited[nr][nc]:
                                    visited[nr][nc] = True
                                    q.append((nr, nc))
                            elif status[nr][nc] == 2:
                                # Frozen cells can be reached but not moved from.
                                # They can be reached from multiple different free components.
                                if last_seen_frozen[nr][nc] != component_id:
                                    last_seen_frozen[nr][nc] = component_id
                                    count += 1

                if count > max_freedom:
                    max_freedom = count

    # Handle the case where all non-magnet cells are frozen (Sample 2)
    # The minimum degree of freedom for any '.' cell is 1.
    if max_freedom == 0:
        for r in range(H):
            for c in range(W):
                if grid[r][c] == '.':
                    max_freedom = 1
                    break

    print(max_freedom)

if __name__ == "__main__":
    solve()

