import sys

def solve():
    # Set recursion depth just in case, though not using recursion here
    sys.setrecursionlimit(2000)

    # Read N and M
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # Use float('inf') for unreachable distances
    INF = float('inf')

    # Initialize adjacency matrix for Floyd-Warshall
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    ptr = 2
    for _ in range(M):
        u = int(input_data[ptr]) - 1
        v = int(input_data[ptr + 1]) - 1
        w = int(input_data[ptr + 2])
        dist[u][v] = min(dist[u][v], w)
        ptr += 3

    # Floyd-Warshall algorithm to find all-pairs shortest paths
    # The problem constraints guarantee no negative cycles.
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF: continue
            for j in range(N):
                if dist[k][j] == INF: continue
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # DP for Traveling Salesperson Problem variant
    # dp[mask][i] = minimum weight to visit set of vertices represented by 'mask',
    # ending at vertex 'i'.
    dp = [[INF] * N for _ in range(1 << N)]

    # Initial state: start at any vertex i
    for i in range(N):
        dp[1 << i][i] = 0

    # Bitmask DP
    for mask in range(1, 1 << N):
        for i in range(N):
            if dp[mask][i] == INF:
                continue

            # Try to go to vertex j that has not been visited yet
            for j in range(N):
                if not (mask & (1 << j)):
                    if dist[i][j] != INF:
                        new_mask = mask | (1 << j)
                        new_dist = dp[mask][i] + dist[i][j]
                        if dp[new_mask][j] > new_dist:
                            dp[new_mask][j] = new_dist

    # The answer is the minimum weight to visit all vertices (mask = (1 << N) - 1)
    ans = INF
    final_mask = (1 << N) - 1
    for i in range(N):
        ans = min(ans, dp[final_mask][i])

    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()

```

