def numberOfBeautifulIntegers(low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def count_beautiful(n: int) -> int:
        s = str(n)

        @lru_cache(None)
        def dp(idx, is_less, is_started, diff, rem):
            # diff is (count of even digits - count of odd digits)
            # rem is the running remainder modulo k
            if idx == len(s):
                return 1 if is_started and diff == 0 and rem == 0 else 0

            res = 0
            limit = int(s[idx]) if not is_less else 9

            for digit in range(limit + 1):
                new_is_less = is_less or (digit < limit)
                new_is_started = is_started or (digit > 0)

                if not new_is_started:
                    # Still leading zeros
                    res += dp(idx + 1, new_is_less, False, 0, 0)
                else:
                    # Processing actual digits
                    new_diff = diff + (1 if digit % 2 == 0 else -1)
                    new_rem = (rem * 10 + digit) % k
                    res += dp(idx + 1, new_is_less, True, new_diff, new_rem)
            return res

        return dp(0, False, False, 0, 0)

    return count_beautiful(high) - count_beautiful(low - 1)
