def minBalancedPartitions(s: str) -> int:
    n = len(s)

    def is_balanced(sub: str) -> bool:
        if not sub:
            return False
        counts = {}
        for char in sub:
            counts[char] = counts.get(char, 0) + 1

        freq_set = set(counts.values())
        return len(freq_set) == 1

    # dp[i] will store the minimum number of substrings for prefix s[:i]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            # Check if the substring s[j:i] is balanced
            # Optimization: only check if dp[j] is reachable
            if dp[j] != float('inf'):
                substring = s[j:i]
                if is_balanced(substring):
                    dp[i] = min(dp[i], dp[j] + 1)

    return dp[n]
```

