def minLength(s: str) -> int:
    stack = []

    for char in s:
        if not stack:
            stack.append(char)
            continue

        # Check if the current character forms "AB" or "CD" with the top of the stack
        if (stack[-1] == 'A' and char == 'B') or (stack[-1] == 'C' and char == 'D'):
            stack.pop()
        else:
            stack.append(char)

    return len(stack)
