def maximumLength(s: str) -> int:
    n = len(s)
    max_len = -1

    # Iterate through all possible lengths from n-2 down to 1
    # Since we need a substring to occur at least thrice, the max length can't exceed n-2
    for length in range(n - 2, 0, -1):
        counts = {}

        # Check every substring of the current length
        for i in range(n - length + 1):
            substring = s[i:i + length]

            # A substring is special if all its characters are the same
            if all(char == substring[0] for char in substring):
                counts[substring] = counts.get(substring, 0) + 1

                # If we find a special substring that occurs at least thrice,
                # because we are iterating from longest to shortest, this is our answer.
                if counts[substring] >= 3:
                    return length

    return max_len
