def solve(s: str, k: int) -> int:
    n = len(s)

    # Precompute changes needed to make a substring s[i:j+1] a semi-palindrome
    # cost[i][j] stores this value
    cost = [[0] * n for _ in range(n)]

    def get_semi_cost(sub):
        m = len(sub)
        if m < 2:
            return float('inf')

        min_changes = m
        # A semi-palindrome must have a divisor d such that 1 <= d < m
        for d in range(1, m):
            if m % d == 0:
                current_changes = 0
                # For each group of indices having the same modulo d
                # they must form a palindrome.
                # The length of each group is m // d.
                # Total groups is d.
                # Each group consists of sub[i], sub[i+d], sub[i+2d], ...
                # We need to make each of these d groups a palindrome.
                # Wait, the rule is: indices that have the same modulo d form a palindrome.
                # The set of characters at {i, i+d, i+2d, ...} form a string.
                # However, the standard interpretation for this problem (like LeetCode 1278/1301 variant):
                # For each i from 0 to d-1, the sequence sub[i], sub[i+d], ..., sub[i+(m/d-1)d]
                # must be a palindrome when viewed as a sequence.
                # This means sub[i + j*d] must equal sub[i + (m/d - 1 - j)*d]
                num_groups = m // d
                for i in range(d):
                    for j in range(num_groups // 2):
                        if sub[i + j * d] != sub[i + (num_groups - 1 - j) * d]:
                            current_changes += 1
                min_changes = min(min_changes, current_changes)
        return min_changes

    for i in range(n):
        for j in range(i + 1, n):
            cost[i][j] = get_semi_cost(s[i:j+1])

    # dp[i][j] = min changes to partition s[0...j-1] into i semi-palindromes
    dp = [[float('inf')] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for i in range(1, k + 1):
        for j in range(1, n + 1):
            # Try splitting at p, where the last substring is s[p:j]
            # Since a semi-palindrome length >= 2, p <= j-2
            for p in range(0, j - 1):
                if dp[i-1][p] != float('inf'):
                    dp[i][j] = min(dp[i][j], dp[i-1][p] + cost[p][j-1])

    return int(dp[k][n])
```

