def stringIndices(wordsContainer, wordsQuery):
    # The problem asks for the longest common suffix. 
    # A Trie storing words in reverse is ideal for this.

    # We need to keep track of the "best" index for each node in the Trie.
    # "Best" is defined as: smallest length, then smallest original index.

    trie = {}

    # Pre-calculate the global best index for queries with no common suffix
    best_idx_global = 0
    min_len_global = len(wordsContainer[0])
    for i in range(1, len(wordsContainer)):
        if len(wordsContainer[i]) < min_len_global:
            min_len_global = len(wordsContainer[i])
            best_idx_global = i

    def update_trie(word, idx):
        curr = trie
        # Update root-level or common nodes with the best index seen so far
        # This helps in finding the result for any suffix depth
        for char in reversed(word):
            if char not in curr:
                curr[char] = {'best_idx': idx}
                curr = curr[char]
            else:
                curr = curr[char]
                # Update the best index at this node if the new word is shorter
                # or if the length is same but index is smaller (implicit by order)
                existing_idx = curr['best_idx']
                if len(word) < len(wordsContainer[existing_idx]):
                    curr['best_idx'] = idx
                # Note: if lengths are equal, we keep the earlier index (existing_idx)

    # Initialize trie with the global best for the root (empty suffix)
    trie['best_idx'] = best_idx_global

    # Build the trie
    for i, word in enumerate(wordsContainer):
        # Update the root information for the empty string case manually
        if len(word) < len(wordsContainer[trie['best_idx']]):
            trie['best_idx'] = i

        curr = trie
        for char in reversed(word):
            if char not in curr:
                curr[char] = {'best_idx': i}
            curr = curr[char]
            # Check if this word is a better representative for this node
            if len(word) < len(wordsContainer[curr['best_idx']]):
                curr['best_idx'] = i

    ans = []
    for query in wordsQuery:
        curr = trie
        last_best = trie['best_idx']
        for char in reversed(query):
            if char in curr:
                curr = curr[char]
                last_best = curr['best_idx']
            else:
                break
        ans.append(last_best)

    return ans
