import sys

def solve():
    # Read all input at once for performance
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    t_prime = input_data[1]
    s_list = input_data[2:]

    len_t = len(t_prime)
    results = []

    for i in range(n):
        s = s_list[i]
        len_s = len(s)

        # Condition check based on length difference
        diff_len = len_s - len_t

        if abs(diff_len) > 1:
            continue

        possible = False

        if diff_len == 0:
            # Case: T' is equal to T OR T' is T with one char changed
            diff_count = 0
            for char_s, char_t in zip(s, t_prime):
                if char_s != char_t:
                    diff_count += 1
                if diff_count > 1:
                    break
            if diff_count <= 1:
                possible = True

        elif diff_len == 1:
            # Case: T' is T with one char deleted (S is longer than T')
            # Check if T' is S with one char removed
            p_s = 0
            p_t = 0
            mismatch = 0
            while p_t < len_t:
                if s[p_s] == t_prime[p_t]:
                    p_s += 1
                    p_t += 1
                else:
                    mismatch += 1
                    p_s += 1
                    if mismatch > 1:
                        break
            if mismatch <= 1:
                possible = True

        elif diff_len == -1:
            # Case: T' is T with one char inserted (S is shorter than T')
            # Check if S is T' with one char removed
            p_s = 0
            p_t = 0
            mismatch = 0
            while p_s < len_s:
                if s[p_s] == t_prime[p_t]:
                    p_s += 1
                    p_t += 1
                else:
                    mismatch += 1
                    p_t += 1
                    if mismatch > 1:
                        break
            if mismatch <= 1:
                possible = True

        if possible:
            results.append(i + 1)

    # Output the count and the 1-based indices
    print(len(results))
    print(*(results))

