def minAnagramLength(s: str) -> int:
    from collections import Counter

    n = len(s)

    def check(length):
        # The base counts for the first potential string t
        target_counts = Counter(s[0:length])

        # Check every subsequent block of size 'length'
        for i in range(length, n, length):
            block_counts = Counter(s[i:i + length])
            if block_counts != target_counts:
                return False
        return True

    # The length of t must be a divisor of the length of s
    # We check divisors in increasing order to find the minimum length
    for length in range(1, n + 1):
        if n % length == 0:
            if check(length):
                return length
    return n
