import math
from itertools import combinations

def findKthSmallest(coins, k):
    # Sort coins and remove multiples to minimize the size of the set
    coins.sort()
    unique_coins = []
    for c in coins:
        is_multiple = False
        for u in unique_coins:
            if c % u == 0:
                is_multiple = True
                break
        if not is_multiple:
            unique_coins.append(c)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        if a == 0 or b == 0: return 0
        return abs(a * b) // gcd(a, b)

    # Precompute inclusion-exclusion terms
    n = len(unique_coins)
    subsets = []
    for i in range(1, n + 1):
        for combo in combinations(unique_coins, i):
            curr_lcm = combo[0]
            for j in range(1, len(combo)):
                curr_lcm = lcm(curr_lcm, combo[j])
            # Store (lcm, coefficient) where coefficient is 1 for odd size, -1 for even
            subsets.append((curr_lcm, 1 if i % 2 == 1 else -1))

    def count_multiples(val):
        count = 0
        for l, coeff in subsets:
            count += coeff * (val // l)
        return count

    # Binary search for the k-th smallest value
    low = 1
    high = min(unique_coins) * k
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if count_multiples(mid) >= k:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return ans
