        idx += W

    # Read grid B
    B = []
    for i in range(H):
        B.append([int(x) for x in input_data[idx:idx+W]])
        idx += W

    def count_inversions(p):
        inv = 0
        for i in range(len(p)):
            for j in range(i + 1, len(p)):
                if p[i] > p[j]:
                    inv += 1
        return inv

    min_ops = float('inf')

    # Generate all permutations of rows and columns
    # A permutation p means the i-th row/col of B matches the p[i]-th row/col of A
    row_perms = list(permutations(range(H)))
    col_perms = list(permutations(range(W)))

    found = False
    for p_row in row_perms:
        for p_col in col_perms:
            match = True
            for i in range(H):
                for j in range(W):
                    # B[i][j] should be A[p_row[i]][p_col[j]]
                    if B[i][j] != A[p_row[i]][p_col[j]]:
                        match = False
                        break
                if not match:
                    break

            if match:
                found = True
                # The number of adjacent swaps to reach a permutation is its inversion count
                ops = count_inversions(p_row) + count_inversions(p_col)
                if ops < min_ops:
                    min_ops = ops

    if not found:
        print("-1")
    else:
        print(min_ops)

