def minimumString(a: str, b: str, c: str) -> str:
    from itertools import permutations

    def merge(s1: str, s2: str) -> str:
        """Merges two strings such that s2 is appended to s1 with maximum overlap."""
        if s2 in s1:
            return s1
        for i in range(min(len(s1), len(s2)), 0, -1):
            if s1.endswith(s2[:i]):
                return s1 + s2[i:]
        return s1 + s2

    def get_combined(s1: str, s2: str, s3: str) -> str:
        """Combines three strings in a specific order."""
        res12 = merge(s1, s2)
        return merge(res12, s3)

    ans = ""
    # Check all 6 permutations of the three strings
    for p in permutations([a, b, c]):
        current = get_combined(p[0], p[1], p[2])

        if ans == "":
            ans = current
        else:
            # If current is shorter, or same length but lexicographically smaller
            if len(current) < len(ans):
                ans = current
            elif len(current) == len(ans):
                if current < ans:
                    ans = current

    return ans
