import sys
from collections import deque

def solve():
    # Read H, W, T
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    H = int(input_data[0])
    W = int(input_data[1])
    T = int(input_data[2])
    grid = input_data[3:]

    start = None
    goal = None
    candies = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'G':
                goal = (r, c)
            elif grid[r][c] == 'o':
                candies.append((r, c))

    # Nodes: start is 0, goal is N+1, candies are 1 to N
    nodes = [start] + candies + [goal]
    N = len(candies)
    num_nodes = len(nodes)

    # Distance matrix between important nodes
    dist = [[float('inf')] * num_nodes for _ in range(num_nodes)]

    for i in range(num_nodes):
        r_start, c_start = nodes[i]
        dists = [[-1] * W for _ in range(H)]
        dists[r_start][c_start] = 0
        queue = deque([(r_start, c_start)])

        while queue:
            r, c = queue.popleft()
            d = dists[r][c]
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != '#' and dists[nr][nc] == -1:
                    dists[nr][nc] = d + 1
                    queue.append((nr, nc))

        for j in range(num_nodes):
            tr, tc = nodes[j]
            if dists[tr][tc] != -1:
                dist[i][j] = dists[tr][tc]

    # Check if goal is reachable
    if dist[0][num_nodes - 1] > T:
        print("-1")
        return

    # TSP-like DP
    # dp[mask][i] = min time to visit candy set 'mask' ending at candy 'i'
    # mask is a bitmask of length N (candies only)
    dp = [[float('inf')] * N for _ in range(1 << N)]

    for i in range(N):
        dp[1 << i][i] = dist[0][i + 1]

    for mask in range(1, 1 << N):
        for i in range(N):
            if dp[mask][i] > T:
                continue
            for j in range(N):
                if not (mask & (1 << j)):
                    new_mask = mask | (1 << j)
                    new_dist = dp[mask][i] + dist[i + 1][j + 1]
                    if new_dist < dp[new_mask][j]:
                        dp[new_mask][j] = new_dist

    max_candies = 0
    # Case: No candies visited
    if dist[0][num_nodes - 1] <= T:
        max_candies = 0

    # Case: Some candies visited
    for mask in range(1, 1 << N):
        count = bin(mask).count('1')
        if count <= max_candies:
            continue
        for i in range(N):
            if dp[mask][i] + dist[i + 1][num_nodes - 1] <= T:
                max_candies = count
                break

    print(max_candies)

if __name__ == "__main__":
    solve()
```

