def punishmentNumber(n: int) -> int:
    def can_partition(s, target):
        if not s:
            return target == 0

        # Try every possible split from the current position
        for i in range(1, len(s) + 1):
            num = int(s[:i])
            if num > target:
                break
            if can_partition(s[i:], target - num):
                return True
        return False

    total_punishment = 0
    for i in range(1, n + 1):
        square_str = str(i * i)
        if can_partition(square_str, i):
            total_punishment += i * i

    return total_punishment
