def minimumCost(source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
    # Initialize a distance matrix for all 26 lowercase English letters
    # float('inf') represents that there is no path between characters
    inf = float('inf')
    dist = [[inf] * 26 for _ in range(26)]

    # Distance from a character to itself is 0
    for i in range(26):
        dist[i][i] = 0

    # Fill the initial costs from the given transformation rules
    for u, v, c in zip(original, changed, cost):
        u_idx = ord(u) - ord('a')
        v_idx = ord(v) - ord('a')
        # There might be multiple costs for the same transformation; keep the minimum
        if c < dist[u_idx][v_idx]:
            dist[u_idx][v_idx] = c

    # Use the Floyd-Warshall algorithm to find the shortest path between all pairs of characters
    for k in range(26):
        for i in range(26):
            if dist[i][k] == inf:
                continue
            for j in range(26):
                if dist[k][j] < inf:
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    total_cost = 0
    # Calculate the total cost to transform source to target
    for s_char, t_char in zip(source, target):
        if s_char == t_char:
            continue

        u_idx = ord(s_char) - ord('a')
        v_idx = ord(t_char) - ord('a')

        c = dist[u_idx][v_idx]
        if c == inf:
            return -1
        total_cost += c

    return total_cost
