def countCompleteSubstrings(word: str, k: int) -> int:
    def count_k_freq(s, k):
        count = 0
        n = len(s)
        # There can be at most 26 distinct characters
        # For each possible number of distinct characters 'm'
        # The window size must be exactly m * k
        for m in range(1, 27):
            window_size = m * k
            if window_size > n:
                break

            freq = [0] * 26
            distinct_with_k = 0

            # Sliding window of size window_size
            for i in range(n):
                idx_in = ord(s[i]) - ord('a')
                freq[idx_in] += 1
                if freq[idx_in] == k:
                    distinct_with_k += 1
                elif freq[idx_in] == k + 1:
                    distinct_with_k -= 1

                if i >= window_size:
                    idx_out = ord(s[i - window_size]) - ord('a')
                    if freq[idx_out] == k:
                        distinct_with_k -= 1
                    elif freq[idx_out] == k + 1:
                        distinct_with_k += 1
                    freq[idx_out] -= 1

                if i >= window_size - 1:
                    if distinct_with_k == m:
                        count += 1
        return count

    # Split word into valid blocks where adjacent characters difference <= 2
    ans = 0
    start = 0
    n = len(word)
    for i in range(1, n + 1):
        if i == n or abs(ord(word[i]) - ord(word[i-1])) > 2:
            ans += count_k_freq(word[start:i], k)
            start = i

    return ans
