import sys

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    idx = 0
    N = int(input_data[idx])
    H = int(input_data[idx+1])
    W = int(input_data[idx+2])
    idx += 3

    tiles = []
    for _ in range(N):
        tiles.append((int(input_data[idx]), int(input_data[idx+1])))
        idx += 2

    # Grid to track covered cells
    grid = [[False for _ in range(W)] for _ in range(H)]

    # Used array to keep track of tiles
    used = [False] * N

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r + h):
            for j in range(c, c + w):
                if grid[i][j]:
                    return False
        return True

    def place(r, c, h, w, val):
        for i in range(r, r + h):
            for j in range(c, c + w):
                grid[i][j] = val

    def backtrack():
        # Find the first empty cell
        r, c = -1, -1
        found = False
        for i in range(H):
            for j in range(W):
                if not grid[i][j]:
                    r, c = i, j
                    found = True
                    break
            if found: break

        # If no empty cell is found, the grid is full
        if not found:
            return True

        # Try placing each unused tile
        for i in range(N):
            if not used[i]:
                used[i] = True
                # Try original orientation and rotated orientation
                orientations = set([tiles[i], (tiles[i][1], tiles[i][0])])
                for h, w in orientations:
                    if can_place(r, c, h, w):
                        place(r, c, h, w, True)
                        if backtrack():
                            return True
                        place(r, c, h, w, False)
                used[i] = False
        return False

    if backtrack():
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

