        m = len(s)
        if n < m:
            return 0

        # We need to fill (n - m) prefix positions
        # Each position can have digits from [0, limit]
        # memoization for digit DP
        memo = {}

        def dp(idx, is_less, is_started):
            # If we reached the suffix part
            if idx == n - m:
                # If we are restricted by is_less, we must check if the suffix s 
                # is lexicographically <= the remaining part of num_str
                if is_less:
                    return 1
                else:
                    target_suffix = num_str[n - m:]
                    return 1 if s <= target_suffix else 0

            state = (idx, is_less, is_started)
            if state in memo:
                return memo[state]

            res = 0
            upper = int(num_str[idx]) if not is_less else 9

            for d in range(min(upper, limit) + 1):
                new_is_less = is_less or (d < upper)
                new_is_started = is_started or (d > 0)

                # Digit DP usually handles leading zeros, but the suffix s 
                # is fixed at the end, so we just fill prefix positions.
                res += dp(idx + 1, new_is_less, new_is_started)

            memo[state] = res
            return res

        return dp(0, False, False)

    return count_powerful(str(finish), limit, s) - count_powerful(str(start - 1), limit, s)
```

