    n_squared = n * n
    # Use a frequency map/count array to track occurrences
    count = [0] * (n_squared + 1)

    for row in grid:
        for val in row:
            count[val] += 1

    a = -1
    b = -1

    # Iterate through the range [1, n^2] to find a (repeated) and b (missing)
    for i in range(1, n_squared + 1):
        if count[i] == 2:
            a = i
        elif count[i] == 0:
