def countMatchingSubarrays(nums, pattern):
    """
    Counts the number of subarrays in nums that match the given pattern.

    A subarray nums[i..i+m] matches a pattern of length m if for each k:
    - nums[i+k+1] > nums[i+k] when pattern[k] == 1
    - nums[i+k+1] == nums[i+k] when pattern[k] == 0
    - nums[i+k+1] < nums[i+k] when pattern[k] == -1
    """
    n = len(nums)
    m = len(pattern)
    count = 0

    # Iterate through every possible starting index i of a subarray of length m + 1
    for i in range(n - m):
        match = True
        # Check if the subarray starting at i matches the pattern
        for k in range(m):
            if pattern[k] == 1:
                if not (nums[i + k + 1] > nums[i + k]):
                    match = False
                    break
            elif pattern[k] == 0:
                if not (nums[i + k + 1] == nums[i + k]):
                    match = False
                    break
            elif pattern[k] == -1:
                if not (nums[i + k + 1] < nums[i + k]):
                    match = False
                    break

        if match:
            count += 1

    return count
