def canTraverseAllPairs(nums: list[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    # Pre-check for 1s, which cannot be connected to anything
    for x in nums:
        if x == 1:
            return False

    # Remove duplicates to speed up prime factorization and union-find
    unique_nums = list(set(nums))
    if len(unique_nums) == 1:
        return True

    # Union-Find structure
    # Elements 0 to len(unique_nums)-1 represent indices of unique_nums
    # Elements from max_val + offset represent prime numbers
    max_val = max(unique_nums)
    parent = list(range(len(unique_nums) + max_val + 1))

    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Sieve-like prime factorization to connect indices to their prime factors
    # We map primes to a range beyond the indices of unique_nums
    prime_offset = len(unique_nums)

    for i, val in enumerate(unique_nums):
        temp = val
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                union(i, prime_offset + d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            union(i, prime_offset + temp)

    # Check if all unique numbers belong to the same component
    root = find(0)
    for i in range(1, len(unique_nums)):
        if find(i) != root:
            return False

    return True
