def maximumPrimeDifference(nums: list[int]) -> int:
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    first_prime_idx = -1
    last_prime_idx = -1

    for i, num in enumerate(nums):
        if is_prime(num):
            if first_prime_idx == -1:
                first_prime_idx = i
            last_prime_idx = i

    return last_prime_idx - first_prime_idx
