def specialPerm(nums: list[int]) -> int:
    n = len(nums)
    MOD = 10**9 + 7

    # Memoization table: dp[mask][last_index]
    # mask: bitmask representing the set of numbers already used
    # last_index: index of the last number added to the permutation
    memo = {}

    def solve(mask, last_idx):
        # Base case: if all numbers are used
        if mask == (1 << n) - 1:
            return 1

        state = (mask, last_idx)
        if state in memo:
            return memo[state]

        count = 0
        for next_idx in range(n):
            # If the next_idx-th number has not been used
            if not (mask & (1 << next_idx)):
                # Check the divisibility condition
                if nums[last_idx] % nums[next_idx] == 0 or nums[next_idx] % nums[last_idx] == 0:
                    count = (count + solve(mask | (1 << next_idx), next_idx)) % MOD

        memo[state] = count
        return count

    total_permutations = 0
    # Start the permutation with each element in the array
    for i in range(n):
        total_permutations = (total_permutations + solve(1 << i, i)) % MOD

    return total_permutations
