        for c in range(w):
            if grid[r][c] == '.':
                curr_r, curr_c = r, c
                possible = True
                # Check if the entire path from this starting point is on land
                for move in t:
                    if move == 'L':
                        curr_c -= 1
                    elif move == 'R':
                        curr_c += 1
                    elif move == 'U':
                        curr_r -= 1
                    elif move == 'D':
                        curr_r += 1

                    # Boundary check and land check
                    if not (0 <= curr_r < h and 0 <= curr_c < w) or grid[curr_r][curr_c] == '#':
                        possible = False
                        break

                if possible:
                    possible_starts.append((r, c))

    # The problem asks for the number of distinct current positions
    # after N moves.
    final_positions = set()
    for start_r, start_c in possible_starts:
        curr_r, curr_c = start_r, start_c
        for move in t:
            if move == 'L':
                curr_c -= 1
            elif move == 'R':
                curr_c += 1
            elif move == 'U':
                curr_r -= 1
            elif move == 'D':
                curr_r += 1
        final_positions.add((curr_r, curr_c))

    print(len(final_positions))

