import sys
from itertools import permutations

def solve():
    # Read input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    r_str = input_data[1]
    c_str = input_data[2]

    # Generate all possible row patterns for a row of length N
    # containing exactly one 'A', one 'B', one 'C', and (N-3) '.'
    base_chars = ['A', 'B', 'C'] + ['.'] * (n - 3)
    all_row_patterns = sorted(list(set(permutations(base_chars))))

    # Pre-filter rows based on the leftmost character constraint (R)
    rows_by_r = [[] for _ in range(n)]
    for i in range(n):
        target = r_str[i]
        for p in all_row_patterns:
            # Find the first non-'.' character
            leftmost = None
            for char in p:
                if char != '.':
                    leftmost = char
                    break
            if leftmost == target:
                rows_by_r[i].append(p)

    current_grid = [None] * n

    def check_cols(row_idx):
        # row_idx is the index of the last row filled (0 to n-1)
        # Check column constraints up to row_idx
        for j in range(n):
            col_chars = [current_grid[i][j] for i in range(row_idx + 1) if current_grid[i][j] != '.']

            # Check for duplicates in columns
            if len(col_chars) != len(set(col_chars)):
                return False

            # If the column is finished (row_idx == n-1), check if it has A, B, and C
            if row_idx == n - 1:
                if len(col_chars) != 3:
                    return False

            # Check topmost character constraint (C)
            if col_chars:
                if col_chars[0] != c_str[j]:
                    return False
        return True

    def backtrack(row_idx):
        if row_idx == n:
            return True

        for p in rows_by_r[row_idx]:
            current_grid[row_idx] = p
            if check_cols(row_idx):
                if backtrack(row_idx + 1):
                    return True
        return False

    if backtrack(0):
        print("Yes")
        for row in current_grid:
            print("".join(row))
    else:
        print("No")

if __name__ == "__main__":
    solve()
```

